class LinkedList{ 
    Node head; 

    public void insert(int data){ 
        Node node = new Node(data); 
        if (head == null) { 
            head = node; 
        } 
        else { 
            Node n = head; 
            while (n.next != null) { 
                n = n.next; 
            } 
            n.next = node; 
        } 
    } 
}

def find_anagrams(str):
    # list to store anagrams
    anagrams = [] 

    # create a frequency array of alphabets present in string 
    freq = [0] * 26
    for char in str: 
        freq[ord(char) - ord('a')] += 1

    # Loop through all the elements from 0 to ( 2^length of string – 1 ) 
    for i in range(1<<len(str)): 

        # Convert the number to binary string 
        # and calculate its frequency array 
        temp_freq = list(freq)
        str_bin = bin(i)[2:] 
        n = len(str_bin) 
        for j in range(n): 
            if str_bin[j] == '1': 
                temp_freq[j] -= 1

        # temp_freq is anagram if all element are 0 
        if all(x == 0 for x in temp_freq): 
            anagram = "" 
            for j in range(n):
                if str_bin[j] == '1': 
                    anagram += str[j]
            anagrams.append(anagram)

    print("All anagrams for '"+str +"' are :" + str(anagrams))

